import sys, time, itertools
sys.path.insert(0, '/tmp/hodge/results/klein-coupled-character')
from kcc import *
F, A, q = load()
p = P0
Fp = core.reduce_mod(F, p)
Fi = [pderiv(Fp, i, p) for i in range(NV)]
# diagonal symmetries: exponent differences lattice; characters of Z^6/L. Solve gamma_i = zeta_n^{a_i} with all F-terms equal weight.
exps = list(F.keys())
e0 = exps[0]
diffs = [tuple(e[i]-e0[i] for i in range(NV)) for e in exps[1:]]
import sympy
M = sympy.Matrix(diffs)
# Smith normal form of the lattice L generated by diffs: Z^6/L has invariant factors
from sympy.matrices.normalforms import smith_normal_form
S = smith_normal_form(M, domain=sympy.ZZ)
print('Smith normal form diagonal of exponent-difference lattice:', [S[i,i] for i in range(min(S.shape))])
# the group of diagonal substitutions preserving F up to scalar = Hom(Z^6/L, C*); modulo global scalars (the all-ones vector)
# (a) sigma-weight sectors of Jacobian ring
def jac_dim(deg, par, k):
    mons = wmonomials(deg, par, k)
    idx = {m: i for i, m in enumerate(mons)}
    cols = []
    for i in range(NV):
        for m in monomials(deg - 5):
            col = shift(Fi[i], m, 1, p)
            col = {e: v for e, v in col.items() if (par is None or yparity(e) == par) and (k is None or wt(e) == k)}
            if col: cols.append(col)
    if not cols: return len(mons), 0
    R, C = len(mons), len(cols)
    flat = [0]*(R*C)
    for j, col in enumerate(cols):
        for e, v in col.items(): flat[idx[e]*C + j] = v
    return len(mons), nmod_mat(R, C, flat, p).rank()
for deg, par, label in [(6,1,'q=1 targets (deg 6, Y-odd)'), (6,0,'deg 6 Y-even'), (12,1,'q=2 targets (deg 12, Y-odd)')]:
    tot = 0; out=[]
    for k in range(7):
        nm, rk = jac_dim(deg, par, k); out.append(f'k{k}:{nm-rk}'); tot += nm-rk
    print(label, ' '.join(out), 'total', tot)
